#!/usr/bin/env python3
"""CSV Insights — dependency-free command-line analytics tool.

Usage:
    python3 main.py INPUT.csv [--where COLUMN=VALUE ...] [--group-by COLUMN]
        [--sum COLUMN] [--avg COLUMN] [--output json|csv]
"""

from __future__ import annotations

import csv
import io
import json
import sys
from decimal import Decimal, InvalidOperation
from typing import Sequence


class CsvError(Exception):
    """Fatal error — printed to stderr, exits non-zero."""


def _die(msg: str) -> "typing.NoReturn":
    print(f"error: {msg}", file=sys.stderr)
    sys.exit(1)


# ---------------------------------------------------------------------------
# Argument parsing
# ---------------------------------------------------------------------------

class Args:
    def __init__(self) -> None:
        self.input_path: str | None = None
        self.where: list[tuple[str, str]] = []
        self.group_by: str | None = None
        self.sum_cols: list[str] = []
        self.avg_cols: list[str] = []
        self.output: str = "json"


def parse_args(argv: Sequence[str]) -> Args:
    args = Args()
    positional: list[str] = []
    i = 0
    n = len(argv)
    while i < n:
        tok = argv[i]
        if tok == "--where":
            i += 1
            if i >= n:
                _die("--where requires an argument of the form COLUMN=VALUE")
            args.where.append(_parse_filter(argv[i]))
        elif tok == "--group-by":
            i += 1
            if i >= n:
                _die("--group-by requires a column name")
            if args.group_by is not None:
                _die("--group-by may only be specified once")
            args.group_by = argv[i]
        elif tok == "--sum":
            i += 1
            if i >= n:
                _die("--sum requires a column name")
            args.sum_cols.append(argv[i])
        elif tok == "--avg":
            i += 1
            if i >= n:
                _die("--avg requires a column name")
            args.avg_cols.append(argv[i])
        elif tok == "--output":
            i += 1
            if i >= n:
                _die("--output requires a value (json or csv)")
            val = argv[i]
            if val not in ("json", "csv"):
                _die(f"--output must be 'json' or 'csv', got {val!r}")
            args.output = val
        elif tok.startswith("--"):
            _die(f"unknown option {tok!r}")
        else:
            positional.append(tok)
        i += 1

    if len(positional) != 1:
        _die("exactly one input CSV path is required")
    args.input_path = positional[0]
    return args


def _parse_filter(spec: str) -> tuple[str, str]:
    if "=" not in spec:
        _die(f"--where filter must be COLUMN=VALUE, got {spec!r}")
    col, _, val = spec.partition("=")
    if col == "":
        _die(f"--where filter has empty column in {spec!r}")
    return col, val


# ---------------------------------------------------------------------------
# CSV reading
# ---------------------------------------------------------------------------

def read_csv(path: str) -> tuple[list[str], list[list[str]]]:
    try:
        with open(path, "r", newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            try:
                header = next(reader)
            except StopIteration:
                _die("input file is empty")
            if not header or any(h == "" for h in header):
                _die("header contains an empty column name")
            if len(set(header)) != len(header):
                _die("header columns must be unique")
            rows: list[list[str]] = []
            for lineno, row in enumerate(reader, start=2):
                if len(row) != len(header):
                    _die(
                        f"row {lineno} has {len(row)} fields, expected {len(header)}"
                    )
                rows.append(row)
            return header, rows
    except FileNotFoundError:
        _die(f"input file not found: {path}")
    except OSError as exc:
        _die(f"cannot read {path}: {exc}")


# ---------------------------------------------------------------------------
# Column resolution
# ---------------------------------------------------------------------------

def _require_column(header: list[str], col: str, context: str) -> int:
    if col not in header:
        _die(f"unknown column {col!r} in {context}")
    return header.index(col)


# ---------------------------------------------------------------------------
# Filtering
# ---------------------------------------------------------------------------

def apply_filters(
    header: list[str], rows: list[list[str]], filters: list[tuple[str, str]]
) -> list[list[str]]:
    if not filters:
        return rows
    indices: list[tuple[int, str]] = []
    for col, val in filters:
        idx = _require_column(header, col, "--where")
        indices.append((idx, val))
    out: list[list[str]] = []
    for row in rows:
        if all(row[idx] == val for idx, val in indices):
            out.append(row)
    return out


# ---------------------------------------------------------------------------
# Aggregation
# ---------------------------------------------------------------------------

def _to_decimal(value: str, row_no: int, col: str) -> Decimal:
    s = value.strip()
    if s == "":
        _die(f"blank numeric value in column {col!r} at row {row_no}")
    try:
        return Decimal(s)
    except InvalidOperation:
        _die(f"invalid numeric value {value!r} in column {col!r} at row {row_no}")


def _fmt_decimal(d: Decimal) -> str:
    """Minimal plain decimal string without binary artifacts."""
    # Normalize removes trailing zeros; then format without exponent.
    normalized = d.normalize()
    sign, digits, exp = normalized.as_tuple()
    if exp <= 0:
        # Fixed-point representation.
        text = format(normalized, "f")
    else:
        # exp > 0 means integer with trailing zeros (e.g. Decimal('3E+2'))
        text = format(normalized, "f")
    # Strip leading zeros but keep at least one digit before the decimal point.
    if "." in text:
        int_part, frac_part = text.split(".", 1)
        int_part = int_part.lstrip("0") or "0"
        frac_part = frac_part.rstrip("0")
        if frac_part:
            text = f"{int_part}.{frac_part}"
        else:
            text = int_part
    else:
        text = text.lstrip("0") or "0"
    if sign and text != "0":
        text = "-" + text
    return text


def aggregate(
    header: list[str],
    rows: list[list[str]],
    group_by: str,
    sum_cols: list[str],
    avg_cols: list[str],
) -> tuple[list[str], list[list[str]]]:
    gb_idx = _require_column(header, group_by, "--group-by")
    sum_idx = [(c, _require_column(header, c, "--sum")) for c in sum_cols]
    avg_idx = [(c, _require_column(header, c, "--avg")) for c in avg_cols]

    # Build output header.
    out_header = [group_by]
    for c in sum_cols:
        out_header.append(f"sum_{c}")
    for c in avg_cols:
        out_header.append(f"avg_{c}")

    # Group rows.
    groups: dict[str, list[list[str]]] = {}
    for row in rows:
        key = row[gb_idx]
        groups.setdefault(key, []).append(row)

    out_rows: list[list[str]] = []
    for key in sorted(groups.keys()):
        group_rows = groups[key]
        out_row = [key]
        for col, idx in sum_idx:
            total = Decimal("0")
            for r_no, r in enumerate(group_rows, start=1):
                total += _to_decimal(r[idx], r_no, col)
            out_row.append(_fmt_decimal(total))
        for col, idx in avg_idx:
            total = Decimal("0")
            count = len(group_rows)
            for r_no, r in enumerate(group_rows, start=1):
                total += _to_decimal(r[idx], r_no, col)
            avg = total / Decimal(count)
            out_row.append(_fmt_decimal(avg))
        out_rows.append(out_row)

    return out_header, out_rows


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------

def emit_json(header: list[str], rows: list[list[str]]) -> None:
    data = [dict(zip(header, row)) for row in rows]
    print(json.dumps(data, indent=2, ensure_ascii=False))


def emit_csv(header: list[str], rows: list[list[str]]) -> None:
    buf = io.StringIO()
    writer = csv.writer(buf, quoting=csv.QUOTE_MINIMAL, lineterminator="\r\n")
    writer.writerow(header)
    writer.writerows(rows)
    sys.stdout.write(buf.getvalue())


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main(argv: Sequence[str] | None = None) -> None:
    args = parse_args(argv if argv is not None else sys.argv[1:])

    header, rows = read_csv(args.input_path)

    # Validate columns referenced in filters early.
    for col, _ in args.where:
        _require_column(header, col, "--where")

    rows = apply_filters(header, rows, args.where)

    has_agg = args.sum_cols or args.avg_cols
    if has_agg and args.group_by is None:
        _die("--sum/--avg require --group-by")
    if args.group_by is not None and not has_agg:
        _die("--group-by requires --sum or --avg")

    if args.group_by is not None:
        out_header, out_rows = aggregate(
            header, rows, args.group_by, args.sum_cols, args.avg_cols
        )
    else:
        out_header = header
        out_rows = rows

    if args.output == "json":
        emit_json(out_header, out_rows)
    else:
        emit_csv(out_header, out_rows)


if __name__ == "__main__":
    main()

