    sum_idx = [(c, _col_index(header, c)) for c in sum_cols]
    avg_idx = [(c, _col_index(header, c)) for c in avg_cols]

    groups: dict[str, list[list[str]]] = {}
    for row in data:
        groups.setdefault(row[g_idx], []).append(row)

    out_header = [group_col]
    for c in sum_cols:
        out_header.append(f"sum_{c}")
    for c in avg_cols:
        out_header.append(f"avg_{c}")

    out_rows: list[list[str]] = []
    for gval in sorted(groups):
        rows = groups[gval]
        out: list[str] = [gval]
        for cname, cidx in sum_idx:
            total = Decimal("0")
            for r in rows:
                total += _to_decimal(r[cidx], 0, cname)
            out.append(_decimal_str(total))
        for cname, cidx in avg_idx:
            total = Decimal("0")
            for r in rows:
                total += _to_decimal(r[cidx], 0, cname)
            avg = total / Decimal(len(rows))
            out.append(_decimal_str(avg))
        out_rows.append(out)
    return out_header, out_rows


def _emit_json(header: list[str], rows: list[list[str]]) -> None:
    obj = [dict(zip(header, row)) for row in rows]
    print(json.dumps(obj, indent=2))


def _emit_csv(header: list[str], rows: list[list[str]]) -> None:
    buf = io.StringIO()
    writer = csv.writer(buf, quoting=csv.QUOTE_MINIMAL, lineterminator="\r\n")
    writer.writerow(header)
    writer.writerows(rows)
    sys.stdout.write(buf.getvalue())


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(
        prog="csv-insights",
        description="Dependency-free CSV analytics tool.",
    )
    parser.add_argument("input", help="input CSV file path")
    parser.add_argument("--where", action="append", default=[], metavar="COLUMN=VALUE",
                        help="exact-match filter (repeatable, AND-combined)")
    parser.add_argument("--group-by", metavar="COLUMN", help="grouping column")
    parser.add_argument("--sum", action="append", default=[], metavar="COLUMN",
                        help="sum this column (requires --group-by)")
    parser.add_argument("--avg", action="append", default=[], metavar="COLUMN",
                        help="average this column (requires --group-by)")
    parser.add_argument("--output", choices=["json", "csv"], default="json",
                        help="output format (default: json)")
    args = parser.parse_args(argv)

    filters = [_parse_where(s) for s in args.where]

    if (args.sum or args.avg) and not args.group_by:
        _die("--sum/--avg requires --group-by")
    if args.group_by and not (args.sum or args.avg):
        _die("--group-by requires --sum or --avg")

    header, data = _read_csv(Path(args.input))

    for col, _ in filters:
        _col_index(header, col)
    if args.group_by:
        _col_index(header, args.group_by)
    for c in args.sum + args.avg:
        _col_index(header, c)

    data = _apply_filters(header, data, filters)

    if args.group_by:
        out_header, out_rows = _aggregate(
            header, data, args.group_by, args.sum, args.avg
        )
    else:
        out_header, out_rows = header, data

    if args.output == "json":
        _emit_json(out_header, out_rows)
    else:
        _emit_csv(out_header, out_rows)


if __name__ == "__main__":
    main()

