    if "=" not in spec:
        _die(f"malformed --where filter '{spec}': expected COLUMN=VALUE")
    col, _, val = spec.partition("=")
    if col == "":
        _die(f"malformed --where filter '{spec}': empty column name")
    return col, val


def _read_csv(path: Path) -> tuple[list[str], list[tuple[int, list[str]]]]:
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        _die(f"input file not found: {path}")
    except OSError as exc:
        _die(f"cannot read input file {path}: {exc}")

    reader = csv.reader(io.StringIO(text))
    try:
        rows = list(reader)
    except csv.Error as exc:
        _die(f"CSV parse error: {exc}")

    if not rows:
        _die("input file is empty")

    header = rows[0]
    if any(h == "" for h in header):
        _die("header contains empty column names")
    if len(set(header)) != len(header):
        _die("header columns must be unique")

    data: list[tuple[int, list[str]]] = []
    for i, row in enumerate(rows[1:], start=2):
        if len(row) != len(header):
            _die(f"row {i} has {len(row)} fields, expected {len(header)}")
        data.append((i, row))
    return header, data


def _col_index(header: list[str], name: str) -> int:
    try:
        return header.index(name)
    except ValueError:
        _die(f"unknown column '{name}'")


def _apply_filters(
    header: list[str], data: list[tuple[int, list[str]]], filters: list[tuple[str, str]]
) -> list[tuple[int, list[str]]]:
    if not filters:
        return data
    indices = [(header.index(col), val) for col, val in filters]
    return [(rn, row) for rn, row in data if all(row[idx] == val for idx, val in indices)]


def _to_decimal(value: str, row_no: int, col_name: str) -> Decimal:
    if value.strip() == "":
        _die(f"row {row_no}: column '{col_name}' has a blank numeric value")
